package social

// IconInfo describes a built-in 24x24 vector icon with its display label and
// optional dark and light brand accent colours.
type IconInfo struct {
	Key         string
	Label       string
	Path        string
	AccentDark  string
	AccentLight string
}

// PackageHostInfo describes one Haberdasher package repository host, its
// inline 24x24 vector mark, platform label, domain, and brand accent colours.
type PackageHostInfo struct {
	Host        string
	Label       string
	Domain      string
	Path        string
	AccentDark  string
	AccentLight string
}

// LookupLinkIcon returns built-in icon metadata for a link or community key.
func LookupLinkIcon(key string) (IconInfo, bool) {
	info, ok := linkIcons[key]
	return info, ok
}

// LookupPackageHost returns built-in metadata for a Haberdasher package host.
func LookupPackageHost(host string) (PackageHostInfo, bool) {
	info, ok := packageHosts[host]
	return info, ok
}

